INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(3701, 'Numbers 10:33', 'Numbers', 10, 33, '&nbsp;کله چې خلق د مالِک خُدائ د غرۀ سينا نه روان شول، هغوئ درې ورځې سفر وکړو. د مالِک خُدائ د لوظ صندوق به همېشه د هغوئ نه مخکښې تلو چې د هغوئ دپاره د دمې کولو ځائ پېدا کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3702, 'Numbers 10:34', 'Numbers', 10, 34, '&nbsp;چې هغوئ به چرته خېمې وړلې، نو د ورځې به د مالِک خُدائ وريځ د هغوئ دپاسه وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3703, 'Numbers 10:35', 'Numbers', 10, 35, '&nbsp;چې کله به هم د لوظ صندوق روان شو، نو موسىٰ به وفرمائيل، ”مالِکه خُدايه، پاڅه، خپل دشمنان خوارۀ وارۀ کړه او هغه خلق چې څوک ستا نه نفرت کوى هغوئ دې ته مجبور کړه چې وتښتى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3704, 'Numbers 10:36', 'Numbers', 10, 36, '&nbsp;او چې کله به د لوظ صندوق ودرېدلو، نو هغۀ به وفرمائيل، ”مالِکه خُدايه، بې‌شمېره بنى اِسرائيلو ته راواپس شه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3705, 'Numbers 11:1', 'Numbers', 11, 1, '&nbsp;نو کله چې خلقو د خپلو تکليفونو په حقله مالِک خُدائ ته شکايتونه شروع کړل، نو مالِک خُدائ دا واورېدل، نو هغه سخت غصه شو او په خلقو يې اور راولېږلو او اور د هغوئ خِلاف بل وو او د کېمپ بهرنى اړخ يوه برخه يې وسوزوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3706, 'Numbers 11:2', 'Numbers', 11, 2, '&nbsp;خلقو موسىٰ ته د مدد دپاره چغې کړې، هغۀ مالِک خُدائ ته سوال وکړو نو اور قلار شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3707, 'Numbers 11:3', 'Numbers', 11, 3, '&nbsp;نو د هغه ځائ نوم تبيعره شو، ځکه چې هلته د مالِک خُدائ اور د هغوئ په کېمپ کښې لګېدلے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3708, 'Numbers 11:4', 'Numbers', 11, 4, '&nbsp;د پردى مُلک څۀ مسافرو د بنى اِسرائيلو سره سفر کولو. د هغوئ غوښې ته ډېر زيات زړۀ وشو او هم داسې په خپله بنى اِسرائيلو هم شکايت شروع کړو او وې وئيل، ”کاش چې لږه غوښه خو وے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3709, 'Numbers 11:5', 'Numbers', 11, 5, '&nbsp;په مِصر کښې چې مونږ کوم کبان غوښتل هغه مو خوړل او مونږ ته مفت مِلاوېدل. هغه بادرنګ، هِندوانې، ګندانه، پياز او اوږه راياده کړئ چې مونږ به خوړل؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3710, 'Numbers 11:6', 'Numbers', 11, 6, '&nbsp;خو اوس مونږ د دې نه پوزې له راغلو، د خوړلو نور هيڅ نشته خو بس دا من دى چې هره ورځ زمونږ مخې ته پراتۀ وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3711, 'Numbers 11:7', 'Numbers', 11, 7, '&nbsp;من د دڼيا د تخم په شان واړۀ وُو او رنګ يې زېړ بخن وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3712, 'Numbers 11:10', 'Numbers', 11, 10, '&nbsp;موسىٰ د ټولو خلقو شکايتونه واورېدل چې هغوئ قبيلې قبيلې د خپلو خېمو په دروازو کښې ولاړ وُو. هغه پرېشان وو ځکه چې مالِک خُدائ هغوئ ته په قهر وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3713, 'Numbers 11:11', 'Numbers', 11, 11, '&nbsp;او هغۀ مالِک خُدائ ته وفرمائيل، ”تۀ زما سره دومره بد سلوک ولې کوې؟ تۀ زما نه ولې نارضا يې؟ تا د دې ټولو خلقو ذمه وارى ما له ولې راکړې ده؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3714, 'Numbers 11:12', 'Numbers', 11, 12, '&nbsp;هغوئ خو ما نۀ دى پېدا کړى او نۀ زما بچى دى. زۀ دې ولې د يوې خِدمتګارې په شان شم چې د پيو ماشوم هغه مُلک ته يوسم چې تا يې د هغوئ د پلار نيکۀ سره وعده کړې ده؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3715, 'Numbers 11:13', 'Numbers', 11, 13, '&nbsp;زۀ دې ټولو خلقو له غوښه د کوم ځائ نه ورکړم؟ ځکه چې هغوئ ما ته ژاړى او زما نه غوښه غواړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3716, 'Numbers 11:14', 'Numbers', 11, 14, '&nbsp;زۀ يواځې د دې ټولو خلقو ذمه وارى نۀ شم اخستلے، دا بوج زما دپاره ډېر دروند دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3717, 'Numbers 11:15', 'Numbers', 11, 15, '&nbsp;کۀ تۀ زما سره هم دغه شان سلوک کوې، نو په ما رحم وکړه او ما ووژنه، کۀ تۀ زما نه رضا يې، نو ما د خپل غم ليدلو نه وساته.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3718, 'Numbers 11:16', 'Numbers', 11, 16, '&nbsp;مالِک خُدائ موسىٰ ته وفرمائيل، ”د بنى اِسرائيلو اويا مشران راجمع کړه چې هغوئ د مشرانو په توګه منلے شوى وى، هغوئ ما له زما د حضور خېمې ته راوله او هغوئ ته ووايه چې هغوئ هلته تا سره ودريږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3719, 'Numbers 11:17', 'Numbers', 11, 17, '&nbsp;زۀ به لاندې راشم او هلته به تا سره خبرې وکړم او چې ما کوم روح تا له درکړے دے د هغې نه به لږ واخلم او هغوئ له به يې ورکړم. بيا به هغوئ ستا مدد کوى او چې د دې خلقو ذمه وارى واخلى، نو دا ذمه وارى به يواځې ستا په سر نۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3720, 'Numbers 11:18', 'Numbers', 11, 18, '&nbsp;اوس خلقو ته ووايه، چې د سبا دپاره ځانونه پاک کړئ، تاسو ته به د خوړلو دپاره غوښه مِلاو شى. مالِک خُدائ ستاسو ژړا اورېدلې ده چې تاسو وئيل چې کاش زمونږ سره لږه غوښه وے او چې زمونږ حالت په مِصر کښې ښۀ وو. اوس به مالِک خُدائ تاسو له غوښه درکړى او تاسو به يې خورئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3721, 'Numbers 11:19', 'Numbers', 11, 19, '&nbsp;دا به تاسو نۀ صِرف يو دوه، پينځۀ يا لس شل ورځې خورئ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3722, 'Numbers 11:20', 'Numbers', 11, 20, '&nbsp;بلکې ټوله مياشت به يې خورئ، چې ستاسو د پوزو نه بهر راوځى او زړۀ به مو ترې موړ شى. هم داسې به وشى ځکه چې تاسو د مالِک خُدائ سپکاوے کړے دے کوم چې دلته ستاسو په مينځ کښې دے او تاسو هغۀ ته دا شکايت کړے دے چې مونږ ولې مِصر پرېښودلے دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3723, 'Numbers 11:21', 'Numbers', 11, 21, '&nbsp;موسىٰ مالِک خُدائ ته وفرمائيل، ”دلته زما سره شپږ لاکه خلق دى او تۀ وائې چې تۀ به هغوئ له د يوې مياشتې غوښه ورکړې؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3724, 'Numbers 11:22', 'Numbers', 11, 22, '&nbsp;څاروى او ګډې دې د هغوئ دپاره حلالې کړے شى څۀ؟ ولې په سمندر کښې ټول کبان به د هغوئ مړولو دپاره کافى وى؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3725, 'Numbers 11:23', 'Numbers', 11, 23, '&nbsp;مالِک خُدائ ورته وفرمائيل، ”زما د طاقت څۀ حد شته؟ تۀ به زر وګورې چې ما څۀ وئيلى دى چې هغه کيږى او کۀ نۀ کيږى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3726, 'Numbers 11:24', 'Numbers', 11, 24, '&nbsp;نو موسىٰ بهر ووتلو او چې مالِک خُدائ څۀ فرمائيلى وُو هغه يې خلقو ته وفرمائيل. هغۀ اويا مشران راجمع کړل او د خېمې نه ګېرچاپېره يې ودرول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3727, 'Numbers 11:25', 'Numbers', 11, 25, '&nbsp;بيا مالِک خُدائ په وريځو کښې لاندې راغلو او د هغۀ سره يې خبرې وکړې. کوم روح يې چې موسىٰ له ورکړے وو د هغې نه يې لږ واخستلو او هغه اويا مشرانو له يې ورکړو. کله چې په هغوئ باندې روح نازل شو نو هغوئ د لږ وخت دپاره د پېغمبرانو په شان خبرې کولې. خو د دې نه پس بيا داسې ونۀ شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3728, 'Numbers 11:26', 'Numbers', 11, 26, '&nbsp;د هغه اويا مشرانو نه دوه مشران، اِلداد او ميداد، په خېمو کښې پاتې وُو او د مالِک خُدائ د حضور خېمې ته تلى نۀ وُو. او په هغوئ باندې روح نازل شو او هغوئ په خېمو کښې د پېغمبرانو په شان خبرې شروع کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3729, 'Numbers 11:27', 'Numbers', 11, 27, '&nbsp;يو ځوان منډه کړه چې موسىٰ ته ووائى چې اِلداد او ميداد په خېمو کښې د پېغمبرانو په شان خبرې کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3730, 'Numbers 11:28', 'Numbers', 11, 28, '&nbsp;بيا د نون زوئ يشوَع، کوم چې د ځوانۍ د وخت نه د موسىٰ مدد کوونکے وو، هغۀ موسىٰ ته وفرمائيل، ”زما نېکه هغوئ منع کړه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3731, 'Numbers 11:29', 'Numbers', 11, 29, '&nbsp;موسىٰ جواب ورکړو، ”تۀ په ما غېرت کوې څۀ؟ زۀ غواړم چې مالِک خُدائ خپل روح خپلو ټولو خلقو ته ورکړى او ټول د پېغمبرانو په شان شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3732, 'Numbers 11:30', 'Numbers', 11, 30, '&nbsp;بيا موسىٰ او د بنى اِسرائيلو مشران واپس کېمپ ته لاړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3733, 'Numbers 11:31', 'Numbers', 11, 31, '&nbsp;ناڅاپه مالِک خُدائ يوه هوا راوستله چې هغې د سمندر د طرف نه مړَزان راوړل، چې د زمکې نه يو ګز اوچت الوتل. دا په خېمو باندې او د خېمو نه ګېرچاپېره هر طرف ته لرې لرې پورې کښېناستل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3734, 'Numbers 11:32', 'Numbers', 11, 32, '&nbsp;نو په هغه ټوله ورځ او شپه او په دوېمه ټوله ورځ، خلقو مړَزان راونيول، هيچا هم د زرو کلو نه کم نۀ وُو رانيولى. هغوئ دا د اوچولو دپاره د ټولو خېمو نه ګېرچاپېره خوارۀ کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3735, 'Numbers 11:33', 'Numbers', 11, 33, '&nbsp;کله چې لا د هغوئ سره ښۀ ډېره غوښه وه، نو مالِک خُدائ خلقو ته په قهر شو او په خلقو يې يوه لويه وبا راولېږله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3736, 'Numbers 11:34', 'Numbers', 11, 34, '&nbsp;د هغه ځائ نوم ”د لالچيانو قبرونه“ شو، ځکه چې هغوئ هلته هغه خلق ښخ کړل د کومو چې غوښې ته زړۀ شوے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3737, 'Numbers 11:35', 'Numbers', 11, 35, '&nbsp;خلقو د هغه ځائ نه حصيروت ته سفر وکړو او هلته اوسېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3738, 'Numbers 12:1', 'Numbers', 12, 1, '&nbsp;بيا موسىٰ يوه حبشۍ ښځه وادۀ کړه، نو مريم او هارون په دې وجه په هغۀ اِعتراض وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3739, 'Numbers 12:2', 'Numbers', 12, 2, '&nbsp;هغوئ ووئيل، ”مالِک خُدائ صِرف د موسىٰ په ذريعه خبرې کړې دى څۀ؟ هغۀ زمونږ په ذريعه خبرې نۀ دى کړې څۀ؟“ هغوئ چې څۀ ووئيل نو مالِک خُدائ هغه واورېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3740, 'Numbers 12:3', 'Numbers', 12, 3, '&nbsp;موسىٰ يو ډېر عاجز سړے وو، هغه د زمکې په مخ د ټولو خلقو نه زيات عاجز وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3741, 'Numbers 12:4', 'Numbers', 12, 4, '&nbsp;ناڅاپه مالِک خُدائ موسىٰ، هارون او مريم ته وفرمائيل، ”تاسو درې واړه بهر زما د حضور خېمې ته لاړ شئ.“ نو هغوئ لاړل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3742, 'Numbers 12:5', 'Numbers', 12, 5, '&nbsp;او مالِک خُدائ د وريځې په ستن کښې لاندې راغلو، د خېمې په دروازه کښې ودرېدلو او هارون او مريم يې راوغوښتل. هغوئ دواړه وروړاندې شول،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3743, 'Numbers 12:6', 'Numbers', 12, 6, '&nbsp;او مالِک خُدائ هغوئ ته وفرمائيل، ”اوس زما خبرې په کولاو غوږُونو واورئ. کله چې ستاسو په مينځ کښې پېغمبران وى، نو زۀ خپل ځان هغوئ ته په خيال کښې څرګندوم او زۀ د هغوئ سره د هغوئ په خوب کښې خبرې کوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3744, 'Numbers 12:7', 'Numbers', 12, 7, '&nbsp;خو زۀ خپل خِدمتګار موسىٰ سره داسې نۀ کوم، هغه ما د خپلو خلقو بنى اِسرائيلو مشر جوړ کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3745, 'Numbers 12:8', 'Numbers', 12, 8, '&nbsp;نو زۀ د هغۀ سره مخامخ خبرې کوم، صفا او واضِحه خبرې ورسره کوم، هغۀ زۀ ليدلے يم. تاسو دا جرأت څنګه کوئ چې زما د خِدمت کوونکى موسىٰ خِلاف خبرې کوئ؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3746, 'Numbers 12:9', 'Numbers', 12, 9, '&nbsp;مالِک خُدائ هغوئ ته په قهر شو، او هغه لاړو', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3747, 'Numbers 12:10', 'Numbers', 12, 10, '&nbsp;او کله چې د خېمې نه وريځ اوچته شوه، نو د مريمې څرمن ناڅاپه په سخته بيمارۍ پټه شوه او د واورې په شان سپينه شوه. کله چې هارون ورته وکتل نو وې ليدل چې د هغې څرمن په بيمارۍ پټه وه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3748, 'Numbers 12:11', 'Numbers', 12, 11, '&nbsp;هغۀ موسىٰ ته ووئيل، ”صاحِبه، زمونږ د کم عقلتوب د ګناه په وجه دا سزا مونږ له مۀ راکوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3749, 'Numbers 12:12', 'Numbers', 12, 12, '&nbsp;د مريم نه داسې څۀ مۀ جوړوه لکه چې يو ماشوم مړ پېدا شوے وى او نيمه غوښه يې نۀ وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3750, 'Numbers 12:13', 'Numbers', 12, 13, '&nbsp;نو موسىٰ مالِک خُدائ ته فرياد وکړو چې، ”خُدايه پاکه، هغه روغه کړه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3751, 'Numbers 12:14', 'Numbers', 12, 14, '&nbsp;مالِک خُدائ ورته وفرمائيل، ”کۀ پلار ورله په مخ تُوکلے وے، نو هغې به اووۀ ورځې خپل شرم نۀ وو برداشت کړے څۀ؟ نو هغه دې اووۀ ورځې د خېمو نه بهر کړے شى او د هغې نه پس هغه واپس راولئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3752, 'Numbers 12:15', 'Numbers', 12, 15, '&nbsp;مريم اووۀ ورځې د خېمو نه بهر کړے شوه او چې تر کومې پورې هغه واپس نۀ وه راوستلے شوې نو خلقو سفر نۀ کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3753, 'Numbers 12:16', 'Numbers', 12, 16, '&nbsp;بيا هغوئ د حصيروت نه لاړل او د فاران په صحرا کښې يې خېمې ولګولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3754, 'Numbers 13:1', 'Numbers', 13, 1, '&nbsp;مالِک خُدائ موسىٰ ته وفرمائيل چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3755, 'Numbers 13:2', 'Numbers', 13, 2, '&nbsp;”د دولسو قبيلو د هرې يوې قبيلې نه يو يو مشر خوښ کړه او هغوئ د جاسوسانو په توګه ولېږه چې د کنعان مُلک وګورى، کوم چې زۀ بنى اِسرائيلو له ورکوم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3756, 'Numbers 13:3', 'Numbers', 13, 3, '&nbsp;نو موسىٰ هغوئ د فاران د صحرا نه د مالِک خُدائ د حُکم په مطابق ولېږل، چې هغوئ ټول د بنى اِسرائيلو مشران وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3757, 'Numbers 13:4', 'Numbers', 13, 4, '&nbsp;د هغوئ نومونه دا وُو يعنې د روبين قبيلې نه، سموع زوئ د زکور،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3758, 'Numbers 13:5', 'Numbers', 13, 5, '&nbsp;د شمعون قبيلې نه، سافط زوئ د حورى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3759, 'Numbers 13:6', 'Numbers', 13, 6, '&nbsp;د يهوداه قبيلې نه، کالب زوئ د يفُنه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3760, 'Numbers 13:7', 'Numbers', 13, 7, '&nbsp;د يساکار قبيلې نه، اِجال زوئ د يوسف،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3761, 'Numbers 13:8', 'Numbers', 13, 8, '&nbsp;د اِفرائيم قبيلې نه، هوسيع زوئ د نون،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3762, 'Numbers 13:9', 'Numbers', 13, 9, '&nbsp;د بنيامين قبيلې نه، فلطى زوئ د رفُو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3763, 'Numbers 13:10', 'Numbers', 13, 10, '&nbsp;د زبولون قبيلې نه، جدى‌اېل زوئ د سودى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3764, 'Numbers 13:11', 'Numbers', 13, 11, '&nbsp;د منسى قبيلې نه، جدى زوئ د سوسى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3765, 'Numbers 13:12', 'Numbers', 13, 12, '&nbsp;د دان قبيلې نه، عمى‌اېل زوئ د جملى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3766, 'Numbers 13:13', 'Numbers', 13, 13, '&nbsp;د آشر قبيلې نه، ستُور زوئ د ميکائيل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3767, 'Numbers 13:14', 'Numbers', 13, 14, '&nbsp;د نفتالى قبيلې نه، نحبى زوئ د وُفسى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3768, 'Numbers 13:15', 'Numbers', 13, 15, '&nbsp;د جاد قبيلې نه، جيواېل زوئ د ماکى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3769, 'Numbers 13:16', 'Numbers', 13, 16, '&nbsp;دا هغه سړى دى چې موسىٰ د هغه مُلک د جاسوسۍ دپاره ولېږل. هغۀ د نون د زوئ هوسيع نوم يشوَع ته بدل کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3770, 'Numbers 13:17', 'Numbers', 13, 17, '&nbsp;کله چې موسىٰ هغوئ لېږل، نو هغوئ ته يې وفرمائيل چې، ”د دې ځائ نه د صحرا په لار لاړ شئ او بيا د کنعان غريزې علاقې ته ورننوځئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3771, 'Numbers 13:18', 'Numbers', 13, 18, '&nbsp;وې ګورئ چې هغه څۀ رنګه مُلک دے، چې کوم خلق په کښې اوسيږى، هغوئ تکړه دى او کۀ کمزورى دى، لږ دى او کۀ ډېر دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3772, 'Numbers 13:19', 'Numbers', 13, 19, '&nbsp;وې ګورئ چې هغه زمکه ښۀ ده او کۀ ښۀ نۀ ده او چې هغه خلق په خېمو کښې اوسيږى يا په داسې ښارونو کښې اوسيږى چې دېوالونه ترې نه تاو وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3773, 'Numbers 13:20', 'Numbers', 13, 20, '&nbsp;وګورئ چې هغه زمکه زرخېزه او کۀ شاړه ده او ونې بوټى په کښې شته او کۀ نشته. او تکړه شئ چې هلته کومه مېوه کيږى لږه ترې نه راوړئ.“ دا هغه موسم وو چې انګور په پخېدو شروع وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3774, 'Numbers 13:21', 'Numbers', 13, 21, '&nbsp;نو هغه سړى د صحرا په طرف لاړل او هغه مُلک يې د صين صحرا نه واخله تر رِحوب پورې وکتلو، چې د حمات درې ته نزدې دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3775, 'Numbers 13:22', 'Numbers', 13, 22, '&nbsp;هغوئ اول د هغه مُلک جنوبى برخې ته ننوتل او حبرون ته راغلل، چرته چې د اخيمان، سيسى او تلمى قبيلې اوسېدلې چې هغوئ عناقيان وُو او د دېوانو د نسل اولاد وو. حبرون د مِصرى ښار ضُعن نه اووۀ کاله مخکښې آباد کړے شوے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3776, 'Numbers 13:23', 'Numbers', 13, 23, '&nbsp;هغوئ د اسکال وادۍ ته راغلل او هلته هغوئ يوه څانګه راماته کړه چې د انګورو يوه غنچه ورباندې وه او دومره درنه وه چې دا دوو سړو په يو ډانګ باندې يو خوا بل خوا راځوړنده کړه او يو يې وړله. هغوئ څۀ انار او اينځر هم يوړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3777, 'Numbers 13:24', 'Numbers', 13, 24, '&nbsp;په هغه وادۍ باندې ”اسکال“ يعنې د انګورو غنچه نوم کېښودے شو ځکه چې بنى اِسرائيلو هلته د انګورو غنچه شوکولې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3778, 'Numbers 13:25', 'Numbers', 13, 25, '&nbsp;هغه مُلک د څلوېښتو ورځو د کتلو نه پس، جاسوسان راواپس شول', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3779, 'Numbers 13:26', 'Numbers', 13, 26, '&nbsp;او موسىٰ، هارون او د بنى اِسرائيلو ټول قوم ته د فاران په صحرا کښې قادِس ته راغلل. جاسوسانو هغه خبر ورله راوړو چې څۀ يې ليدلى وُو او هغه مېوه يې ورته وښودله چې کومه يې راوړې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3780, 'Numbers 13:27', 'Numbers', 13, 27, '&nbsp;هغوئ موسىٰ ته ووئيل، ”مونږ هغه مُلک وکتلو چې زرخېز او آباد وو او دا يې لږه شان مېوه ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3781, 'Numbers 13:28', 'Numbers', 13, 28, '&nbsp;خو د هغه ځائ اوسېدونکى تکړه دى او د هغوئ ښارونه غټ دى او د ښارونو نه يې دېوالونه تاو دى. او د دې نه علاوه، مونږ هلته د دېوانو اولاد هم وليدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3782, 'Numbers 13:29', 'Numbers', 13, 29, '&nbsp;عماليقيان د هغه مُلک په صحرا کښې اوسيږى، حِتيان، يبوسيان او اموريان د غرونو په مُلک کښې اوسيږى، او کنعانيان د مديترانى د سمندر او د اُردن سيند سره اوسيږى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3783, 'Numbers 13:30', 'Numbers', 13, 30, '&nbsp;کالب هغه خلق غلى کړل کومو چې د موسىٰ خِلاف شکايتونه کول او وې وئيل، ”راځئ چې په هغه مُلک حمله وکړُو او وې نيسو، ځکه مونږ ښۀ تکړه يُو او ورباندې برے موندے شُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3784, 'Numbers 13:31', 'Numbers', 13, 31, '&nbsp;خو هغه سړو ووئيل کوم چې د کالب سره تلى وُو، ”نه. مونږ تکړه نۀ يُو چې حمله ورباندې وکړُو، هغه خلق زمونږ نه زيات طاقتور دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3785, 'Numbers 13:32', 'Numbers', 13, 32, '&nbsp;نو هغوئ د بنى اِسرائيلو په مينځ کښې د هغه مُلک په حقله غلط خبر خور کړو کوم چې هغوئ ليدلے وو. هغوئ ووئيل، ”په هغه مُلک کښې دومره څۀ هم نۀ پېدا کيږى چې د هغه ځائ اوسېدونکى خلق يې وخورى. کوم خلق چې مونږ وليدل ټول لوړ لوړ وُو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3786, 'Numbers 13:33', 'Numbers', 13, 33, '&nbsp;او هلته مونږ دېوان هم وليدل، چې د عناق اولاد دے. مونږ ته خپل ځانونه داسې معلومېدل لکه چې مُلخان يُو او مونږ به هغوئ ته خامخا هم داسې ښکارېدلو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3787, 'Numbers 14:1', 'Numbers', 14, 1, '&nbsp;بيا ټوله شپه خلقو په چغو چغو وژړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3788, 'Numbers 14:2', 'Numbers', 14, 2, '&nbsp;هغوئ د موسىٰ او هارون خِلاف شکايت وکړو او وې وئيل، ”دا به ډېره ښۀ وے چې د مِصر په مُلک کښې يا دلته په دې صحرا کښې مړۀ وے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3789, 'Numbers 14:3', 'Numbers', 14, 3, '&nbsp;مالِک خُدائ مونږ هغه مُلک ته ولې بوځى؟ مونږ به په جنګ کښې ووژلے شُو او زمونږ ښځې او بچى به ونيولے شى. دا به ښۀ نۀ وى څۀ چې واپس مِصر ته لاړ شُو؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3790, 'Numbers 14:4', 'Numbers', 14, 4, '&nbsp;نو هغوئ يو بل ته ووئيل، ”راځئ چې يو مشر خوښ کړُو او مِصر ته واپس لاړ شُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3791, 'Numbers 14:5', 'Numbers', 14, 5, '&nbsp;بيا موسىٰ او هارون د هغه خلقو په وړاندې په زمکه را پرېوتل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3792, 'Numbers 14:6', 'Numbers', 14, 6, '&nbsp;او د نون زوئ يشوَع او کالب د يفُنه زوئ چې د نورو کسانو سره هغه مُلک کتلے وو، نو هغوئ هغه دوه کسان وُو چې د خفګان نه يې خپلې جامې وشلولې', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3793, 'Numbers 14:7', 'Numbers', 14, 7, '&nbsp;او خلقو ته يې وفرمائيل، ”کوم مُلک چې مونږ وکتلو هغه ډېر زيات ښۀ مُلک دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3794, 'Numbers 14:8', 'Numbers', 14, 8, '&nbsp;کۀ مالِک خُدائ زمونږ نه رضا وى نو هغه به مونږ هلته بوځى، هغه مُلک ته چې زرخېز او آباد وى او مونږ له به يې راکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3795, 'Numbers 14:9', 'Numbers', 14, 9, '&nbsp;د مالِک خُدائ خِلاف بغاوت مۀ کوئ او د هغه خلقو نه مۀ يرېږئ کوم چې هلته اوسيږى. هغوئ له شکست ورکول مونږ ته آسان دى. مالِک خُدائ زمونږ مل دے او هغه خُدايانو له يې شکست ورکړے دے چې هغوئ يې بچ کول، نو مۀ يرېږئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3796, 'Numbers 14:10', 'Numbers', 14, 10, '&nbsp;ټول قوم وئيل چې هغوئ به سنګسار کړى، خو ناڅاپه خلقو وليدل چې د مالِک خُدائ د حضور جلال د خېمې دپاسه راڅرګند شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3797, 'Numbers 14:11', 'Numbers', 14, 11, '&nbsp;مالِک خُدائ موسىٰ ته وفرمائيل، ”دا خلق به تر کومې پورې زما نه نفرت کوى؟ او په ما باندې به اعتماد نۀ کوى، اګر چې د هغوئ په مينځ کښې ما ډېرې معجزې کړې دى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3798, 'Numbers 14:12', 'Numbers', 14, 12, '&nbsp;زۀ به په هغوئ وبا راولم او هلاک به يې کړم، خو زۀ به تا د يو داسې قوم پلار نيکۀ جوړ کړم چې هغه به د دې خلقو نه لوئ او طاقتور وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3799, 'Numbers 14:13', 'Numbers', 14, 13, '&nbsp;خو موسىٰ مالِک خُدائ ته وفرمائيل، ”تا د خپل طاقت سره دا خلق د مِصر نه راوويستل. کله چې مِصريان خبر شى چې تا د خپلو خلقو سره څۀ کړى دى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3800, 'Numbers 14:14', 'Numbers', 14, 14, '&nbsp;نو هغوئ به د دې مُلک اوسېدونکو ته ووائى چا چې د مخکښې نه دا اورېدلى دى چې مالِکه خُدايه، تۀ زمونږ مل يې، او چې کله ستا وريځ زمونږ دپاسه ولاړه وى نو تۀ راته مخامخ ښکارېږې او چې تۀ زمونږ د ورځې د وريځې په ستن کښې او د شپې د اور په ستن کښې لارښودنه کوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');